import{_ as a,o as i,c as t,al as s}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"PPS Time Synchronization (PX4 Integration)","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced/pps_time_sync.md","filePath":"en/advanced/pps_time_sync.md"}'),r={name:"en/advanced/pps_time_sync.md"};function n(o,e,l,p,h,d){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="pps-time-synchronization-px4-integration" tabindex="-1">PPS Time Synchronization (PX4 Integration) <a class="header-anchor" href="#pps-time-synchronization-px4-integration" aria-label="Permalink to &quot;PPS Time Synchronization (PX4 Integration)&quot;">​</a></h1><p><a href="https://en.wikipedia.org/wiki/Pulse-per-second_signal" target="_blank" rel="noreferrer">Pulse Per Second</a> (PPS) time synchronization provides high-precision timing for GNSS receivers. This page explains how PPS is integrated into PX4 and how to configure it.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>PPS (Pulse Per Second) is a timing signal provided by GNSS receivers that outputs an electrical pulse once per second, synchronized to UTC time. The PPS signal provides a highly accurate timing reference that PX4 can use to:</p><ul><li>Refine GNSS time measurements and compensate for clock drift</li><li>Provide precise UTC timestamps for camera capture events (for photogrammetry and mapping applications)</li><li>Enable offline position refinement through accurate time correlation</li></ul><h2 id="supported-hardware" tabindex="-1">Supported Hardware <a class="header-anchor" href="#supported-hardware" aria-label="Permalink to &quot;Supported Hardware&quot;">​</a></h2><p>PPS time synchronization can be supported on flight controllers that have a hardware timer input pin that can be configured for PPS capture, by <a href="#enable-pps-driver-in-board-configuration">enabling the PPS capture driver</a> in the board configuration.</p><p>Supported boards include (at time of writing):</p><ul><li><a href="./../flight_controller/ark_v6x">Ark FMUv6x</a></li><li>Auterion FMUv6x</li><li>Auterion FMUv6s</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="enable-pps-driver-in-board-configuration" tabindex="-1">Enable PPS Driver in Board Configuration <a class="header-anchor" href="#enable-pps-driver-in-board-configuration" aria-label="Permalink to &quot;Enable PPS Driver in Board Configuration&quot;">​</a></h3><p>The <a href="./../modules/modules_driver#pps-capture">PPS capture driver</a> must be enabled in the board configuration. This is done by adding the following to your board&#39;s configuration:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_DRIVERS_PPS_CAPTURE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=y</span></span></code></pre></div><h3 id="configure-pps-parameters" tabindex="-1">Configure PPS Parameters <a class="header-anchor" href="#configure-pps-parameters" aria-label="Permalink to &quot;Configure PPS Parameters&quot;">​</a></h3><p>The configuration varies depending on your flight controller hardware.</p><h4 id="fmuv6x" tabindex="-1">FMUv6X <a class="header-anchor" href="#fmuv6x" aria-label="Permalink to &quot;FMUv6X&quot;">​</a></h4><p>For FMUv6X-based flight controllers, configure PWM AUX Timer 3 and Function 9:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PWM_AUX_TIM3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PWM_AUX_FUNC9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2064</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PPS_CAP_ENABLE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><h4 id="fmuv6s" tabindex="-1">FMUv6S <a class="header-anchor" href="#fmuv6s" aria-label="Permalink to &quot;FMUv6S&quot;">​</a></h4><p>For FMUv6S-based flight controllers, configure PWM MAIN Timer 3 and Function 10:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PWM_MAIN_TIM3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PWM_MAIN_FUNC10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2064</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PPS_CAP_ENABLE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><h4 id="multi-gps-setups" tabindex="-1">Multi-GPS Setups <a class="header-anchor" href="#multi-gps-setups" aria-label="Permalink to &quot;Multi-GPS Setups&quot;">​</a></h4><p>If you have multiple GPS receivers, set <code>PPS_CAP_GPS_ID</code> to the device ID of the GPS receiver that emits the PPS signal. When set to <code>0</code> (default), the driver uses the first available GPS instance.</p><p>You can find the device ID by running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sensor_gps</span></span></code></pre></div><h3 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h3><p>The wiring configuration depends on your specific flight controller.</p><h4 id="skynode-x-fmuv6x" tabindex="-1">Skynode X (FMUv6x) <a class="header-anchor" href="#skynode-x-fmuv6x" aria-label="Permalink to &quot;Skynode X (FMUv6x)&quot;">​</a></h4><p>Connect the PPS signal from your GNSS module to the flight controller using the 11-pin or 6-pin GPS connector:</p><p>For detailed pinout information, refer to:</p><ul><li><a href="https://docs.auterion.com/hardware-integration/skynode/peripherals/gps#pinouts" target="_blank" rel="noreferrer">Skynode GPS Peripherals - Pinouts</a></li></ul><h4 id="skynode-s-fmuv6s" tabindex="-1">Skynode S (FMUv6S) <a class="header-anchor" href="#skynode-s-fmuv6s" aria-label="Permalink to &quot;Skynode S (FMUv6S)&quot;">​</a></h4><p>For FMUv6S, you need to route the PPS signal separately:</p><ol><li>Connect your GNSS module using the standard 6-pin GPS connector: <a href="https://docs.auterion.com/hardware-integration/skynode-s/interfaces#gps" target="_blank" rel="noreferrer">Skynode S GPS Interface</a></li><li>Connect the PPS signal from your GNSS module to the <strong>PPM_IN</strong> pin: <a href="https://docs.auterion.com/hardware-integration/skynode-s/interfaces#extras-1" target="_blank" rel="noreferrer">Skynode S Extras 1 Interface</a></li></ol><h4 id="ark-jetson-carrier-board-fmuv6x" tabindex="-1">ARK Jetson Carrier Board (FMUv6x) <a class="header-anchor" href="#ark-jetson-carrier-board-fmuv6x" aria-label="Permalink to &quot;ARK Jetson Carrier Board (FMUv6x)&quot;">​</a></h4><p>For ARK FMUv6X on the Jetson carrier board:</p><ol><li>Connect your GNSS module using either the 10-pin or 6-pin GPS connector: <a href="./../flight_controller/ark_pab#gps1">ARK PAB GPS1 Interface</a></li><li>Connect the PPS signal to the <strong>FMU_CAP</strong> pin: <a href="./../flight_controller/ark_pab#adio">ARK PAB ADIO Interface</a></li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After configuring PPS, you can verify that it is working correctly:</p><ol><li><p>Connect to the <a href="./../debug/system_console">PX4 System Console</a> (via MAVLink shell or serial console).</p></li><li><p>Wait for GNSS fix.</p></li><li><p>Check the PPS capture status to confirm it is up and running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pps_capture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div></li><li><p>You can also check the <a href="./../msg_docs/PpsCapture">PpsCapture</a> uORB topic</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pps_capture</span></span></code></pre></div><p>Where you should see: <code>timestamp</code>, <code>rtc_timestamp</code>, and <code>pps_rate_exceeded_counter</code>.</p></li></ol><h3 id="pps-capture-driver" tabindex="-1">PPS Capture Driver <a class="header-anchor" href="#pps-capture-driver" aria-label="Permalink to &quot;PPS Capture Driver&quot;">​</a></h3><p>The PPS capture driver is located in <code>src/drivers/pps_capture</code> and uses hardware timer input capture to precisely measure the arrival time of each PPS pulse.</p><p>Key features:</p><ul><li>Sub-microsecond pulse capture precision (hardware-dependent)</li><li>Automatic drift calculation and compensation</li><li>Integration with the GNSS driver for refined time stamping</li></ul><p>See also:</p><ul><li><a href="./../modules/modules_driver#pps-capture">PPS Capture Driver Documentation</a></li><li><a href="./../msg_docs/PpsCapture">PpsCapture Message</a></li></ul><h3 id="time-synchronization-flow" tabindex="-1">Time Synchronization Flow <a class="header-anchor" href="#time-synchronization-flow" aria-label="Permalink to &quot;Time Synchronization Flow&quot;">​</a></h3><ol><li>GNSS module sends position/time data at ~1-20 Hz.</li><li>GNSS module outputs PPS pulse at 1 Hz, precisely aligned to UTC second boundary.</li><li>PPS capture driver measures the exact time of the PPS pulse arrival using hardware timer.</li><li>Driver calculates the offset between GNSS time (from UART data) and autopilot clock (from PPS measurement).</li><li>This offset is used to correct GNSS timestamps and improve sensor fusion accuracy.</li></ol><p>The PPS signal provides much higher temporal precision than the transmitted time data, which has latency and jitter from serial communication.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If the PPS driver does not send any data for 5 seconds (despite having <code>PPS_CAP_ENABLE</code> set to 1), the corresponding <code>SENS_GPS*_DELAY</code> parameter will be used instead for estimating the latency.</p></div>`,50)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
